function GridLayer({viewport,config}){
 const bounds={minX:0,minY:0,maxX:PAPER.width,maxY:PAPER.height};
 const lines=useMemo(()=>computeGridLines(bounds,config,viewport.zoom),[config.mode,config.spacing,config.angle,config.showMajor,config.majorEvery,config.adaptive,viewport.zoom]);
 if(config.mode===GRID_MODES.OFF)return null;
 return <svg className="gridLayer" width={PAPER.width} height={PAPER.height} viewBox={`0 0 ${PAPER.width} ${PAPER.height}`}>{lines.map(l=><line key={l.id} className={l.major&&config.showMajor?'major':''} x1={l.a.x} y1={l.a.y} x2={l.b.x} y2={l.b.y}/>)}</svg>;
}

function DocumentationGlyph({e,allEntities}){
 const r=resolveDocumentationEntity(e,allEntities);
 if(e.kind==='dimension'&&r.resolved){
  const a=r.a,b=r.b,dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len,nx=-uy,ny=ux,o=e.offset||28;
  if(e.dimensionType==='angular'){
   const radius=Math.max(22,Math.min(62,r.graphicDistance*.32)),endAngle=Math.atan2(dy,dx),ex=a.x+Math.cos(endAngle)*radius,ey=a.y+Math.sin(endAngle)*radius,large=Math.abs(endAngle)>Math.PI?1:0,sweep=endAngle>=0?1:0;
   return <g className="documentationGlyph dimensionGlyph angularDimension"><line className="extension" x1={a.x} y1={a.y} x2={a.x+radius} y2={a.y}/><line className="extension" x1={a.x} y1={a.y} x2={ex} y2={ey}/><path className="dimensionLine" d={`M ${a.x+radius} ${a.y} A ${radius} ${radius} 0 ${large} ${sweep} ${ex} ${ey}`}/><text x={a.x+Math.cos(endAngle/2)*(radius+14)} y={a.y+Math.sin(endAngle/2)*(radius+14)} textAnchor="middle">{r.label}</text></g>
  }
  let p1={x:a.x+nx*o,y:a.y+ny*o},p2={x:b.x+nx*o,y:b.y+ny*o};
  if(e.dimensionType==='horizontal'){const y=Math.min(a.y,b.y)-Math.abs(o);p1={x:a.x,y};p2={x:b.x,y}}
  if(e.dimensionType==='vertical'||e.dimensionType==='elevation'){const x=Math.max(a.x,b.x)+Math.abs(o);p1={x,y:a.y};p2={x,y:b.y}}
  const ddx=p2.x-p1.x,ddy=p2.y-p1.y,dlen=Math.hypot(ddx,ddy)||1,dux=ddx/dlen,duy=ddy/dlen,dnx=-duy,dny=dux,m={x:(p1.x+p2.x)/2,y:(p1.y+p2.y)/2};
  return <g className={`documentationGlyph dimensionGlyph dimension-${e.dimensionType}`}><line className="extension" x1={a.x} y1={a.y} x2={p1.x} y2={p1.y}/><line className="extension" x1={b.x} y1={b.y} x2={p2.x} y2={p2.y}/><line className="dimensionLine" x1={p1.x} y1={p1.y} x2={p2.x} y2={p2.y}/><path className="arrowHead" d={`M ${p1.x} ${p1.y} l ${dnx*5+dux*8} ${dny*5+duy*8} M ${p1.x} ${p1.y} l ${-dnx*5+dux*8} ${-dny*5+duy*8} M ${p2.x} ${p2.y} l ${dnx*5-dux*8} ${dny*5-duy*8} M ${p2.x} ${p2.y} l ${-dnx*5-dux*8} ${-dny*5-duy*8}`}/><text x={m.x} y={m.y-6} textAnchor="middle">{e.dimensionType==='offset'?'OFFSET · ':''}{r.label}</text></g>
 }
 if(e.kind==='elevation'&&r.resolved)return <g className="documentationGlyph elevationGlyph"><circle cx={r.point.x} cy={r.point.y} r="3"/><line x1={r.point.x} y1={r.point.y} x2={r.x} y2={r.y+14}/><path d={`M ${r.x} ${r.y+14} h 92`}/><text x={r.x+4} y={r.y+10}>{r.label}</text>{e.datum&&<text className="subLabel" x={r.x+4} y={r.y+25}>{e.datum}</text>}</g>;
 if(e.kind==='industrial-coordinate'&&r.resolved){const fmt=v=>Number.isFinite(v)?v.toFixed(2):'—';return <g className="documentationGlyph coordinateGlyph"><circle cx={r.point.x} cy={r.point.y} r="3"/><line x1={r.point.x} y1={r.point.y} x2={r.x} y2={r.y}/><rect x={r.x} y={r.y} width={r.width} height={r.height}/><text x={r.x+6} y={r.y+14}>N {fmt(e.n)} · E {fmt(e.e)}</text><text x={r.x+6} y={r.y+29}>X {fmt(e.xCoord)} · Y {fmt(e.yCoord)} · Z {fmt(e.z)}</text><text x={r.x+6} y={r.y+44}>Datum {e.datum||'—'}</text><text x={r.x+6} y={r.y+59}>Ref. {e.reference||'—'}</text></g>}
 if(e.kind==='flow-arrow'&&r.resolved){const p=r.point,rad=r.angle*Math.PI/180,ux=Math.cos(rad),uy=Math.sin(rad),nx=-uy,ny=ux,a={x:p.x-ux*22,y:p.y-uy*22},b={x:p.x+ux*22,y:p.y+uy*22};return <g className="documentationGlyph flowGlyph"><line x1={a.x} y1={a.y} x2={b.x} y2={b.y}/><path d={`M ${b.x} ${b.y} L ${b.x-ux*11+nx*6} ${b.y-uy*11+ny*6} L ${b.x-ux*11-nx*6} ${b.y-uy*11-ny*6} Z`}/></g>}
 if(e.kind==='north-arrow'){const cx=e.x+e.width/2,cy=e.y+e.height/2;return <g className="documentationGlyph northGlyph" transform={`rotate(${e.rotation||0} ${cx} ${cy})`}><line x1={cx} y1={e.y+e.height*.82} x2={cx} y2={e.y+e.height*.2}/><path d={`M ${cx} ${e.y+4} L ${cx-8} ${e.y+e.height*.28} L ${cx+8} ${e.y+e.height*.28} Z`}/><text x={cx+12} y={e.y+14}>{e.label||'N'}</text></g>}
 return null;
}
function Entity({e,selected,onDown,allEntities}){
 if(e.kind===ANNOTATION_KINDS.TEXT)return <g className={`entity annotationText ${selected?'selected':''}`} onPointerDown={ev=>onDown(ev,e)} data-entity-id={e.id}><rect className="annotationHitBox" x={e.x} y={e.y} width={e.width} height={e.height}/><text x={e.x} y={e.y+e.fontSize}>{String(e.text||'').split('\n').map((line,i)=><tspan key={i} x={e.x} dy={i?e.fontSize*1.25:0}>{line}</tspan>)}</text></g>;
 if(e.kind===ANNOTATION_KINDS.TAG)return <g className={`entity annotationTag ${selected?'selected':''}`} onPointerDown={ev=>onDown(ev,e)} data-entity-id={e.id}><rect x={e.x} y={e.y} width={e.width} height={e.height} rx="3"/><text x={e.x+6} y={e.y+19}>{formatTag(e,allEntities)}</text></g>;
 if(e.kind===ANNOTATION_KINDS.LEADER){const r=resolveLeader(e,allEntities),a=r.anchor,l=r.labelPoint,el=r.elbow||{x:l.x,y:a.y};return <g className={`entity annotationLeader ${selected?'selected':''}`} onPointerDown={ev=>onDown(ev,e)} data-entity-id={e.id}><polyline points={`${a.x},${a.y} ${el.x},${el.y} ${l.x},${l.y}`}/><path className="leaderArrow" d={`M ${a.x} ${a.y} l 10 -4 l -2 9 Z`}/><text x={l.x+5} y={l.y-5}>{e.text}</text></g>}
 if(['dimension','elevation','industrial-coordinate','flow-arrow','north-arrow'].includes(e.kind))return <g className={`entity documentationEntity ${e.kind} ${selected?'selected':''}`} onPointerDown={ev=>onDown(ev,e)} data-entity-id={e.id}><DocumentationGlyph e={e} allEntities={allEntities}/></g>;
 if(isLinearEntity(e)){
  const pipe=isPipeRun(e),styleId=pipe?(e.visualStyle?.id||'PROCESS'):'';
  return <g className={`entity polylineEntity ${pipe?'pipeRunEntity':''} ${pipe?`pipeStyle-${styleId.toLowerCase().replaceAll('_','-')}`:''} ${selected?'selected':''}`} data-pipe-style={styleId||undefined} data-entity-id={e.id} onPointerDown={ev=>onDown(ev,e)}>{pipe&&e.visualStyle?.secondary&&<path className="pipeSecondary" d={polylineToPath(e)}/>}<path className="pipeCenterline" d={polylineToPath(e)}/></g>;
 }
 const cx=e.x+e.width/2,cy=e.y+e.height/2;
 if(e.kind==='industrial-symbol'){const symbol=e.symbolDefinition||getSymbol(e.symbolId);return <g className={`entity industrialSymbol ${selected?'selected':''}`} transform={`rotate(${e.rotation||0} ${cx} ${cy})`} onPointerDown={ev=>onDown(ev,e)} data-entity-id={e.id} data-symbol-id={e.symbolId}><rect className="symbolHitBox" x={e.x} y={e.y} width={e.width} height={e.height}/><SymbolGlyph symbol={e.category==='INSTRUMENTAÇÃO'?{...symbol,displayTag:e.tag||symbol.instrumentCode||e.acronym}:isUx06Symbol(e)?{...symbol,displayText:e.note||e.tag||symbol.acronym}:symbol} x={e.x} y={e.y} width={e.width} height={e.height}/>{e.category!=='INSTRUMENTAÇÃO'&&<text className="symbolEntityLabel" x={cx} y={e.y+e.height+12} textAnchor="middle">{['ANOTAÇÕES','SÍMBOLOS DE FOLHA'].includes(e.category)?String(e.note||e.tag||e.acronym).slice(0,28):e.tag||e.acronym}</text>}</g>}
 return <g className={`entity ${selected?'selected':''}`} transform={`rotate(${e.rotation||0} ${cx} ${cy})`} onPointerDown={ev=>onDown(ev,e)} data-entity-id={e.id}><rect x={e.x} y={e.y} width={e.width} height={e.height} rx="6"/><text x={cx} y={cy-4} textAnchor="middle">{e.name}</text><text className="entityId" x={cx} y={cy+15} textAnchor="middle">{e.id}</text></g>;
}

function SelectionOverlay({bounds,viewport,onHandleDown}){
 if(!bounds)return null;
 const hs=handlePositions(bounds,10/viewport.zoom,30/viewport.zoom),size=hs.size;
 return <g className="selectionOverlay"><rect className="selectionBounds" x={bounds.minX} y={bounds.minY} width={bounds.maxX-bounds.minX} height={bounds.maxY-bounds.minY}/><line className="rotateStem" x1={hs.n.x} y1={hs.n.y} x2={hs.rotate.x} y2={hs.rotate.y}/>{['nw','n','ne','e','se','s','sw','w'].map(id=><rect key={id} className={`handle handle-${id}`} x={hs[id].x-size/2} y={hs[id].y-size/2} width={size} height={size} onPointerDown={e=>onHandleDown(e,id)}/>)}<circle className="rotateHandle" cx={hs.rotate.x} cy={hs.rotate.y} r={size*.58} onPointerDown={e=>onHandleDown(e,'rotate')}/></g>;
}

function PolylineEditingOverlay({line,viewport,onWaypointDown,onSegmentDown,onSegmentDoubleClick}){
 if(!line)return null;
 const r=5/viewport.zoom;
 return <g className="polylineEditing">{line.points.slice(0,-1).map((p,i)=>{const q=line.points[i+1];return <line key={`s-${i}`} className="segmentHit" x1={p.x} y1={p.y} x2={q.x} y2={q.y} onPointerDown={e=>onSegmentDown(e,line,i)} onDoubleClick={e=>onSegmentDoubleClick(e,line,i)}/>})}{line.points.map((p,i)=><circle key={`p-${i}`} className="waypoint" cx={p.x} cy={p.y} r={r} onPointerDown={e=>onWaypointDown(e,line,i)}><title>{`Waypoint ${i+1}`}</title></circle>)}</g>;
}

function ConnectionPoints({entities,graph,viewport,visible}){
 if(!visible)return null;const r=6/viewport.zoom;
 return <g className="connectionPoints">{entities.filter(isPipeRun).flatMap(run=>[
  {point:run.points[0],portId:`${run.id}-PORT-START`,runId:run.id},
  {point:run.points.at(-1),portId:`${run.id}-PORT-END`,runId:run.id}
 ]).map(x=>{const connected=!!graph.ports[x.portId]?.connectedConnectionId;return <circle key={x.portId} className={`connectionPoint ${connected?'connected':''}`} cx={x.point.x} cy={x.point.y} r={r}><title>{`${x.portId}${connected?' · conectado':' · disponível'}`}</title></circle>})}</g>;
}
function SnapOverlay({result,viewport}){
 if(!result?.snapped)return null;const r=7/viewport.zoom,fs=11/viewport.zoom,p=result.point;
 return <g className="snapOverlay">{(result.guides||[]).map((g,i)=>g.axis==='x'?<line key={i} className="smartGuide" x1={g.value} y1={0} x2={g.value} y2={PAPER.height}/>:g.axis==='y'?<line key={i} className="smartGuide" x1={0} y1={g.value} x2={PAPER.width} y2={g.value}/>:null)}<circle className={`snapMarker snap-${result.candidate.type}`} cx={p.x} cy={p.y} r={r}/><text className="snapLabel" x={p.x+10/viewport.zoom} y={p.y-10/viewport.zoom} fontSize={fs}>{snapLabel(result)}</text></g>;
}

