 const ux09MakePdf=async(options,plan,gate)=>{
  if(!plan?.pages?.length)throw Error('Documento sem páginas para exportação');
  if(options.documentMode==='CONTROLLED'){
   const validated=await ux10VerifyFormalSnapshot(documentModel,entities,ux10ReleaseContext);
   if(!validated.allowed)throw Error(validated.reason);
   gate=validated;
  }
  const [{jsPDF},{renderToStaticMarkup}]=await Promise.all([import('jspdf'),import('react-dom/server')]);
  await import('svg2pdf.js');
  let pdf=null;
  for(let i=0;i<plan.pages.length;i++){
   const p=plan.pages[i],size=p.sizeMm,orient=size.width>=size.height?'landscape':'portrait';
   if(!pdf)pdf=new jsPDF({orientation:orient,unit:'mm',format:[size.width,size.height],compress:true,precision:12});
   else pdf.addPage([size.width,size.height],orient);
   const markup=renderToStaticMarkup(<Ux09ExportCanvas page={p} document={documentModel} entities={entities} inspectionStore={inspectionStore} renderEntity={Entity}/>);
   const parsed=new DOMParser().parseFromString(markup,'image/svg+xml');
   if(parsed.getElementsByTagName('parsererror').length)throw Error('Falha na composição SVG da página '+(i+1));
   await pdf.svg(parsed.documentElement,{x:0,y:0,width:size.width,height:size.height});
  }
  if(pdf.getNumberOfPages()!==plan.pages.length)throw Error('Contagem do PDF diferente do plano');
  const controlled=options.documentMode==='CONTROLLED';
  const fileName=ux09FileName(documentModel,plan,{controlled});
  return{pdf,fileName,gate};
 };
 const ux09Export=async(options,plan,gate)=>{
  const result=await ux09MakePdf(options,plan,gate);
  await result.pdf.save(result.fileName);
  if(options.documentMode==='CONTROLLED')setEmissionLog(old=>[...old,ux09EmissionAttempt({plan,gate:result.gate,fileName:result.fileName})]);
 };
 const ux09Print=async(options,plan,gate)=>{
  const tab=window.open('about:blank','_blank');
  try{
   const result=await ux09MakePdf(options,plan,gate);
   const url=URL.createObjectURL(result.pdf.output('blob'));
   if(tab&&!tab.closed){tab.location.href=url;setShellNotice({title:'PDF aberto para impressão',body:'Use Imprimir no visualizador do navegador. O comando não confirma impressão ou assinatura.'})}
   else{await result.pdf.save(result.fileName);setShellNotice({title:'Visualizador bloqueado',body:'O navegador bloqueou a janela. O PDF foi disponibilizado como download.'})}
   if(options.documentMode==='CONTROLLED')setEmissionLog(old=>[...old,ux09EmissionAttempt({plan,gate:result.gate,fileName:result.fileName})]);
  }catch(e){if(tab&&!tab.closed)tab.close();throw e}
 };
