 const move=e=>{
  const s=eventScreen(e),raw=screenToWorld(s,v);setCursor(s);
  const exclude=interaction?.lineId||null,sr=snapped(raw,e,exclude),p=sr.point;setSnapPreview(sr.snapped?sr:null);
  if(!interaction)return;
  if(interaction.type==='pan'){setSnapPreview(null);setV({...interaction.startViewport,panX:interaction.startViewport.panX+e.clientX-interaction.screen.x,panY:interaction.startViewport.panY+e.clientY-interaction.screen.y});return}
  if(interaction.type==='marquee'&&marquee){setSnapPreview(null);setMarquee({...marquee,current:raw,direction:raw.x>=marquee.start.x?'contain':'intersect'});return}
  if(interaction.type==='move'){const ref=snapped(raw,e,null);setEntities(syncMountedSymbolPositions(moveSelection(interaction.startEntities,interaction.ids,ref.point.x-interaction.start.x,ref.point.y-interaction.start.y)));return}
  if(interaction.type==='resize'){setEntities(resizeSelection(interaction.startEntities,interaction.ids,interaction.handle,p,interaction.startBounds));return}
  if(interaction.type==='rotate'){setSnapPreview(null);setEntities(rotateSelection(interaction.startEntities,interaction.ids,interaction.startBounds,interaction.start,raw));return}
  if(interaction.type==='waypoint'){setInteraction(i=>({...i,lastSnap:sr}));setEntities(es=>syncMountedSymbolPositions(es.map(x=>x.id===interaction.lineId?(isPipeRun(x)?movePipeWaypoint(x,interaction.index,p):moveWaypoint(x,interaction.index,p)):x)));return}
  if(interaction.type==='segment'){setSnapPreview(null);setEntities(es=>syncMountedSymbolPositions(es.map(x=>x.id===interaction.lineId?(isPipeRun(x)?movePipeSegment(interaction.startLine,interaction.index,raw.x-interaction.start.x,raw.y-interaction.start.y):moveSegment(interaction.startLine,interaction.index,raw.x-interaction.start.x,raw.y-interaction.start.y)):x)))}
 };
